const term = (title, body, example, trap, priority = 1) => ({title, body, example, trap, priority});
const pattern = (title, body, example, checklist) => ({title, body, example, checklist});

const cssGroups = [
  {title:'Selektory i kaskada', items:[
    term('Selektor typu, klasy i identyfikatora','Wybierz tag, grupę elementów o tej samej klasie albo pojedynczy element z identyfikatorem. Kropka należy do selektora klasy, kratka do selektora id.','p { color: #243; }\n.karta { padding: 16px; }\n#wynik { font-weight: 700; }','W HTML zapisz class="karta", bez kropki.'),
    term('Grupowanie selektorów','Przecinek pozwala zastosować wspólny zestaw deklaracji do kilku niezależnych selektorów.','h1, h2, h3 { line-height: 1.2; }','Zapis h1 h2 opisuje zagnieżdżenie.'),
    term('Potomek i bezpośrednie dziecko','Spacja wybiera dowolnego potomka. Znak > ogranicza dopasowanie do bezpośrednich dzieci.','nav a { color: navy; }\nnav > a { padding: 8px; }','Link wewnątrz li pasuje do nav a, lecz może nie pasować do nav > a.'),
    term('Sąsiednie elementy i atrybuty','A + B wybiera B bezpośrednio po A. Selektor atrybutu sprawdza obecność lub wartość atrybutu.','label + input { display: block; }\ninput[type="email"] { width: 100%; }','Znak + opisuje rodzeństwo, a nie dziecko.'),
    term(':hover, :focus-visible i :checked','Pseudoklasy wybierają element w danym stanie. Używaj ich do reakcji na kursor, fokus klawiatury i zaznaczenie.','a:hover { color: #945; }\nbutton:focus-visible { outline: 3px solid #369; }\ninput:checked { accent-color: #369; }','Pozostaw wyraźny fokus, aby kontrolki dało się obsłużyć klawiaturą.'),
    term(':nth-child i :nth-of-type','Wybierz element według pozycji wśród rodzeństwa. nth-child liczy wszystkie elementy, nth-of-type tylko elementy tego samego typu.','tbody tr:nth-child(even) { background: #eee; }\nli:nth-child(3) { font-weight: bold; }','Numerowanie w pseudoklasie zaczyna się od 1.'),
    term('Specyficzność i kolejność','Dla zwykłych reguł w tym samym pochodzeniu i warstwie id ma większą specyficzność niż klasa, a klasa niż tag. Późniejsza reguła rozstrzyga remis.','.cena { color: green; }\n.cena { color: navy; }','Kaskada uwzględnia też m.in. ważność i warstwy, więc sama liczba id nie wyjaśnia każdej sytuacji.'),
    term('Dziedziczenie','Część właściwości, np. color i font-family, przechodzi z rodzica na potomków. Dziedziczenie ułatwia ustalenie wyglądu tekstu na całej stronie.','body { font-family: Arial, sans-serif; color: #222; }\nbutton { font: inherit; }','Padding i margin elementu nadrzędnego nie są domyślnie dziedziczone.'),
  ]},
  {title:'Rozmiary, odstępy i tekst', items:[
    term('width, height, min-width i max-width','Podaj rozmiar lub jego granice. max-width jest przydatny do ograniczenia treści i obrazów w elastycznym układzie.','.tresc { width: 100%; max-width: 1000px; }\nimg { max-width: 100%; height: auto; }','Jednoczesne wymuszenie szerokości i wysokości obrazu może go rozciągnąć.'),
    term('padding i margin','Padding oddziela zawartość od obramowania. Margin tworzy przestrzeń poza obramowaniem elementu.','.karta { padding: 16px 24px; margin-bottom: 20px; }','W skrócie z dwiema wartościami pierwsza dotyczy góry i dołu, druga boków.'),
    term('border i border-radius','Border rysuje obramowanie. Border-radius zaokrągla narożniki.','.karta { border: 1px solid #bbb; border-radius: 12px; }','Samo border-color nie nada widocznej linii, jeśli styl obramowania to none.'),
    term('box-sizing','Border-box wlicza padding i border do podanej szerokości. Pomaga przewidywać rozmiary kolumn.','* { box-sizing: border-box; }\n.karta { width: 240px; padding: 12px; border: 2px solid; }','Przy content-box obrys tego przykładu ma 268px bez marginesów.'),
    term('Jednostki px, %, rem, em i fr','px opisuje piksel CSS, procent zależy od kontekstu, rem od rozmiaru fontu korzenia, em zwykle od bieżącego fontu. fr dzieli wolne miejsce w Grid.','.tresc { padding: 1rem; width: 90%; }\n.karty { grid-template-columns: 2fr 1fr; }','Znaczenie procentu zależy od właściwości i kontenera.'),
    term('color i background','color ustawia kolor tekstu. background może zdefiniować tło, jego obraz, pozycję i sposób powtarzania.','body { color: #20252b; background: #f3f5f7; }\nheader { background: #234 url("baner.jpg") center / cover; }','Tło i tekst ustaw osobno, gdy czytelność zależy od kontrastu.'),
    term('font-family, font-size, font-weight','Dobierz krój, wielkość i grubość pisma. Końcowa ogólna rodzina działa, gdy wcześniejszy font nie jest dostępny.','body { font-family: Arial, sans-serif; font-size: 16px; }\nh1 { font-size: 2rem; font-weight: 700; }','Nazwa fontu z odstępem wymaga cudzysłowu.'),
    term('line-height, text-align i text-decoration','Ustal wysokość wiersza, wyrównanie tekstu i dekoracje. Jednostkowa line-height skaluje się z fontem.','p { line-height: 1.6; }\nfooter { text-align: center; }\na { text-decoration: underline; }','text-align wyrównuje treść wewnątrz bloku.'),
  ]},
  {title:'Układ strony', items:[
    term('display','Wybierz sposób generowania i układania pudełek elementu, np. block, inline, flex lub grid. Display none usuwa pudełko z układu.','.panel { display: flex; }\n.ukryte { display: none; }','visibility hidden zachowuje miejsce elementu w układzie.'),
    term('Flexbox i flex-direction','Włącz flex na rodzicu. Kierunek row prowadzi główną oś wzdłuż wiersza, column wzdłuż kolumny.','.menu { display: flex; flex-direction: row; }','Właściwości wyrównania zależą od aktualnego kierunku osi.'),
    term('justify-content i align-items','Rozmieść elementy flex na osi głównej i poprzecznej. Typowym zastosowaniem jest wyśrodkowanie lub rozdzielenie nawigacji.','.panel { display: flex; justify-content: space-between; align-items: center; }','justify-content działa na wolnym miejscu osi głównej.'),
    term('flex, flex-wrap i gap','Ustal udział elementów we wzroście i kurczeniu, pozwól przejść do kolejnego wiersza i określ odstęp.','.karty { display: flex; flex-wrap: wrap; gap: 16px; }\n.karta { flex: 1 1 240px; }','Gap tworzy odstępy między elementami, bez zewnętrznej ramki odstępu.'),
    term('Grid i grid-template-columns','Grid ustawia wiersze i kolumny. fr rozdziela wolne miejsce między tory.','.uklad { display: grid; grid-template-columns: 2fr 1fr; gap: 24px; }','Dodaj minmax(0, 1fr), gdy długa treść wypycha elastyczną kolumnę.'),
    term('repeat i minmax','repeat powtarza definicję toru, a minmax określa dolną i górną granicę. To wygodny zapis galerii kart.','.karty { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }','Funkcja minmax działa w definicjach torów Grid.'),
    term('position i bloki odniesienia','Relative zachowuje miejsce elementu i umożliwia przesunięcie. Absolute wyjmuje element ze zwykłego układu i pozycjonuje względem właściwego przodka.','.karta { position: relative; }\n.etykieta { position: absolute; top: 8px; right: 8px; }','Dla znacznika na karcie ustal rodzicowi position relative.'),
    term('fixed, sticky i z-index','Fixed mocuje element do obszaru widoku w typowym układzie. Sticky przełącza go w pozycję przyklejoną w obrębie kontenera. Z-index ustala kolejność w kontekście stosu.','header { position: sticky; top: 0; z-index: 10; }','Z-index nie jest globalnym rankingiem wszystkich elementów.',2),
  ]},
  {title:'Responsywność i detale', items:[
    term('@media','Zastosuj zestaw deklaracji po spełnieniu warunku, np. maksymalnej szerokości okna.','@media (max-width: 700px) {\n  .uklad { grid-template-columns: 1fr; }\n}','Sprawdź układ przy 700 i 701px.'),
    term('overflow','Steruj treścią wykraczającą poza obszar elementu. overflow auto daje przewijanie, gdy jest potrzebne.','.tabela-scroll { overflow-x: auto; }\npre { overflow: auto; }','Ukrycie overflow może odciąć treść potrzebną do zadania.'),
    term('object-fit i aspect-ratio','Zachowaj proporcje pola i określ sposób dopasowania osadzonego obrazu. cover wypełnia pole z możliwym przycięciem.','.miniatura { width: 100%; aspect-ratio: 3 / 2; object-fit: cover; }','Contain zachowuje cały obraz i może pozostawić wolne obszary.'),
    term('float i clear','Float umożliwia opływanie tekstem. Clear przenosi element poniżej wcześniejszych pływających elementów z wybranej strony.','img { float: left; margin-right: 16px; }\nfooter { clear: both; }','W starszym arkuszu możesz spotkać układ kolumn oparty na float.',2),
    term('border-collapse i format tabeli','Scal krawędzie komórek i nadaj im spójne odstępy. To częsty zestaw dla tabel z arkuszy.','table { border-collapse: collapse; width: 100%; }\nth, td { border: 1px solid #777; padding: 8px; }','Parzystość wierszy najlepiej ograniczyć selektorem do tbody.'),
    term('cursor i stany kontrolek','Dobierz kursor i wygląd elementu zależnie od możliwości interakcji. Disabled oznacza kontrolkę wyłączoną.','button { cursor: pointer; }\nbutton:disabled { opacity: .5; cursor: default; }','Wyszarzenie samym CSS-em nie blokuje kliknięcia.',2),
    term('transition i transform','Transition płynnie zmienia wartości po zmianie stanu. Transform wizualnie przesuwa, obraca lub skaluje element.','.karta { transition: transform .2s; }\n.karta:hover { transform: translateY(-3px); }','Transform nie przestawia sąsiednich elementów w normalnym układzie.',2),
    term('Zmienne CSS i ograniczony ruch','Własne właściwości przechowują wartości używane przez var(). Warunek prefers-reduced-motion pozwala ograniczyć animację.',':root { --akcent: #456; }\na { color: var(--akcent); }\n@media (prefers-reduced-motion: reduce) {\n  * { transition: none; }\n}','Nazwy własnych właściwości zaczynają się od dwóch myślników.',2),
  ]},
];

const sqlGroups = [
  {title:'Model i struktura', items:[
    term('Tabela, rekord i kolumna','Tabela zbiera rekordy tego samego rodzaju. Kolumna opisuje cechę, a wiersz jej wartości dla jednej pozycji.','CREATE TABLE produkty (\n  id INT PRIMARY KEY,\n  nazwa VARCHAR(80),\n  cena DECIMAL(7,2)\n);','Kolejność rekordów wyniku ustal przez ORDER BY.'),
    term('PRIMARY KEY','Klucz główny jednoznacznie identyfikuje wiersz. Może składać się z jednej lub kilku kolumn.','CREATE TABLE typy (id INT PRIMARY KEY, nazwa VARCHAR(40));','Klucz główny nie przyjmuje NULL i nie dopuszcza duplikatów.'),
    term('FOREIGN KEY i relacja','Klucz obcy wskazuje rekord w tabeli nadrzędnej i pomaga zachować spójność relacji.','FOREIGN KEY (typ_id) REFERENCES typy(id)','Nazwy łączonych kolumn mogą być różne, ale wartości muszą opisywać tę samą relację.'),
    term('INT, VARCHAR, DECIMAL, DATE','Dobierz typ do znaczenia danych. INT przechowuje liczby całkowite, VARCHAR tekst, DECIMAL wartości o zadanej dokładności, DATE datę.','CREATE TABLE rezerwacje (\n  id INT PRIMARY KEY,\n  klient VARCHAR(80),\n  kwota DECIMAL(8,2),\n  dzien DATE\n);','Kwoty w DECIMAL mają dokładny zapis dziesiętny.'),
    term('NOT NULL, UNIQUE i DEFAULT','Wymuś obecność wartości, unikatowość lub domyślne ustawienie kolumny.','email VARCHAR(120) NOT NULL UNIQUE,\nstatus VARCHAR(20) DEFAULT \'nowy\'','DEFAULT działa przy pominięciu wartości lub użyciu słowa DEFAULT.'),
    term('AUTO_INCREMENT','W MySQL i MariaDB pozwala generować kolejne identyfikatory liczbowe. Zwykle łączy się z kluczem głównym.','CREATE TABLE klienci (id INT PRIMARY KEY AUTO_INCREMENT, imie VARCHAR(50));','Nie używaj automatycznego numeru jako dowodu ciągłości bez braków.',2),
    term('ALTER TABLE','Zmień istniejącą strukturę, np. dodaj kolumnę. Przed zmianą sprawdź obecną tabelę.','ALTER TABLE produkty ADD COLUMN opis VARCHAR(200);','DROP COLUMN usuwa kolumnę wraz z jej danymi.',2),
    term('CREATE VIEW','Widok nadaje nazwę zapytaniu, z którego można korzystać jak z źródła danych.','CREATE VIEW tanie AS\nSELECT id, nazwa, cena FROM produkty WHERE cena < 50;','Widok przechowuje definicję zapytania, a nie niezależną kopię rekordów.',2),
  ]},
  {title:'Odczyt i filtrowanie', items:[
    term('SELECT i FROM','W SELECT podaj potrzebne kolumny, a w FROM źródło danych. Zachowaj kolejność kolumn z polecenia.','SELECT nazwa, cena FROM produkty;','SELECT * może zwrócić zbyt wiele kolumn.'),
    term('AS i DISTINCT','AS nadaje alias. DISTINCT usuwa powtarzające się kombinacje wszystkich wybranych kolumn.','SELECT DISTINCT typ_id AS kategoria FROM produkty;','DISTINCT nazwa, cena usuwa duplikaty pary, a nie samej nazwy.'),
    term('WHERE i operatory porównania','Filtruj rekordy przed grupowaniem. Użyj =, <>, <, >, <= lub >= zależnie od polecenia.','SELECT nazwa FROM produkty WHERE cena >= 20;','Warunek >= obejmuje wartość graniczną.'),
    term('AND, OR i NOT','Połącz warunki. AND wymaga obu, OR co najmniej jednego. Nawiasy określają czytelną kolejność oceny.','SELECT nazwa FROM produkty\nWHERE aktywny = 1 AND (typ_id = 2 OR typ_id = 3);','Bez nawiasów AND ma pierwszeństwo przed OR.'),
    term('LIKE, % i _','Wyszukuj tekst po wzorcu. % oznacza dowolny ciąg, a _ jeden znak.','SELECT nazwa FROM produkty WHERE nazwa LIKE \'Ro%\';','Wzorzec z procentem po obu stronach wyszukuje fragment wewnątrz tekstu.'),
    term('IN i BETWEEN','IN porównuje do zestawu wartości. BETWEEN obejmuje obie granice przedziału.','SELECT nazwa FROM produkty\nWHERE typ_id IN (1, 3) AND cena BETWEEN 10 AND 30;','BETWEEN 10 AND 30 uwzględnia 10 oraz 30.'),
    term('IS NULL i IS NOT NULL','Sprawdź brak wartości. NULL reprezentuje wartość nieznaną lub brak danych.','SELECT id FROM produkty WHERE opis IS NULL;','Porównanie = NULL nie sprawdza braku danych.'),
    term('ORDER BY, ASC i DESC','Ustal kolejność wyniku. ASC sortuje rosnąco, DESC malejąco. Kolejne kolumny rozstrzygają remisy.','SELECT nazwa, cena FROM produkty ORDER BY cena DESC, nazwa ASC;','Bez ORDER BY kolejność jest nieokreślona.'),
    term('LIMIT i OFFSET','W MySQL i MariaDB ogranicz liczbę wierszy i opcjonalnie pomiń początek wyniku.','SELECT id, nazwa FROM produkty ORDER BY id LIMIT 5 OFFSET 10;','Ustal jednoznaczną kolejność, gdy dzielisz wyniki na strony.'),
  ]},
  {title:'Relacje i obliczenia', items:[
    term('INNER JOIN i ON','Połącz rekordy mające dopasowanie według relacji w ON. Aliasy skracają kwalifikowane nazwy kolumn.','SELECT p.nazwa, t.nazwa AS typ\nFROM produkty AS p INNER JOIN typy AS t ON p.typ_id = t.id;','Łącz według relacji z modelu.'),
    term('LEFT JOIN','Zachowaj każdy wiersz lewego źródła, także bez dopasowania. Kolumny prawej strony mogą wtedy zawierać NULL.','SELECT t.nazwa, p.nazwa\nFROM typy AS t LEFT JOIN produkty AS p ON p.typ_id = t.id;','Warunek prawej tabeli w WHERE może usunąć niedopasowane wiersze.'),
    term('COUNT(*) i COUNT(kolumna)','COUNT(*) liczy wiersze. COUNT(kolumna) pomija wartości NULL. Przy LEFT JOIN policz id po stronie dopasowań.','SELECT t.nazwa, COUNT(p.id)\nFROM typy AS t LEFT JOIN produkty AS p ON p.typ_id=t.id\nGROUP BY t.id, t.nazwa;','COUNT(*) daje 1 także dla zachowanego wiersza pustej kategorii.'),
    term('SUM, AVG, MIN i MAX','Agregaty liczą sumę, średnią i skrajne wartości. Zwykle pomijają NULL.','SELECT AVG(cena) AS srednia, MAX(cena) AS najdrozszy FROM produkty;','Średnia jest liczona z niepustych wartości.'),
    term('GROUP BY','Połącz wiersze w grupy, aby agregat policzył wynik osobno dla każdej wartości grupującej.','SELECT typ_id, COUNT(*) AS liczba FROM produkty GROUP BY typ_id;','Wybrane nieagregowane kolumny umieść w GROUP BY, aby wynik był jednoznaczny.'),
    term('HAVING','Filtruj gotowe grupy po agregacji. WHERE może wcześniej ograniczyć rekordy wejściowe.','SELECT typ_id, COUNT(*) FROM produkty\nWHERE aktywny=1 GROUP BY typ_id HAVING COUNT(*) >= 2;','Warunek COUNT(*) umieść w HAVING.'),
    term('Podzapytanie skalarne','Wstaw wynik innego zapytania tam, gdzie potrzebna jest pojedyncza wartość, np. średnia cena.','SELECT nazwa FROM produkty\nWHERE cena > (SELECT AVG(cena) FROM produkty);','Podzapytanie w takim porównaniu ma zwrócić najwyżej jeden wiersz.',2),
    term('Funkcje tekstowe i liczbowe','CONCAT łączy tekst, UPPER zmienia litery, ROUND zaokrągla liczbę. Użyj ich, gdy polecenie wymaga przekształcenia wyniku.','SELECT UPPER(nazwa), ROUND(cena * 1.23, 2) AS brutto FROM produkty;','Alias nie zmienia nazwy kolumny w tabeli.',2),
  ]},
  {title:'Zmiany i administracja', items:[
    term('INSERT INTO','Dodaj rekord. Jawna lista kolumn wskazuje, do czego należą kolejne wartości.','INSERT INTO produkty (id, nazwa, cena, typ_id) VALUES (10, \'Most\', 18.50, 1);','Zachowaj kolejność kolumn i wartości.'),
    term('UPDATE i SET','Zmień wartości wybranych rekordów. Najpierw sprawdź je przez SELECT z tym samym WHERE.','UPDATE produkty SET cena = 17.50 WHERE id = 4;','Bez WHERE aktualizacja obejmie wszystkie wiersze.'),
    term('DELETE FROM','Usuń rekordy spełniające warunek. Sprawdź zakres i relacje przed wykonaniem.','DELETE FROM produkty WHERE id = 4;','DELETE usuwa dane, a DROP TABLE całą tabelę.'),
    term('START TRANSACTION, COMMIT i ROLLBACK','W tabelach transakcyjnych grupuj operacje danych, a potem zatwierdź lub wycofaj je.','START TRANSACTION;\nUPDATE produkty SET cena=20 WHERE id=4;\nROLLBACK;','W MySQL i MariaDB wiele poleceń DDL, np. ALTER TABLE, powoduje niejawne zatwierdzenie.',2),
    term('CREATE USER, GRANT i REVOKE','Załóż konto bazy i przydziel tylko potrzebne prawa. Ćwicz w swojej testowej bazie.','CREATE USER \'raport\'@\'localhost\' IDENTIFIED BY \'haslo_cwiczebne\';\nGRANT SELECT ON inf03.produkty TO \'raport\'@\'localhost\';','Nazwa konta obejmuje użytkownika i host. Użytkownik używany w przykładzie jest kontem ćwiczebnym.',2),
    term('Import i eksport SQL','Import odtwarza strukturę oraz dane z pliku. Eksport służy m.in. wykonaniu kopii i przeniesieniu bazy.','-- Po imporcie sprawdź dane:\nSELECT COUNT(*) FROM produkty;','Sprawdź właściwą bazę, liczbę tabel i polskie znaki. Sam komunikat importu nie potwierdza całej zawartości.'),
    term('Kolejność klauzul','Zapisuj klauzule w porządku składni SQL. W praktyce przydaje się stały szablon do odtworzenia z pamięci.','SELECT typ_id, COUNT(*)\nFROM produkty\nWHERE aktywny=1\nGROUP BY typ_id\nHAVING COUNT(*) > 1\nORDER BY typ_id\nLIMIT 5;','WHERE i HAVING pełnią różne role i mają różne miejsca.'),
  ]},
];

const jsGroups = [
  {title:'Składnia i wartości', items:[
    term('const i let','const tworzy wiązanie bez ponownego przypisania, a let pozwala przypisać nową wartość. Obie deklaracje mają zakres blokowy.','const stawka = 12.5;\nlet suma = 0;\nsuma = stawka * 2;','const nie zamraża automatycznie zawartości obiektu.'),
    term('Typy, null i undefined','Rozróżniaj liczbę, tekst, wartość logiczną i obiekt. null bywa jawnym brakiem obiektu, a undefined m.in. brakiem wartości zwracanej.','const cena = 12;\nconst nazwa = "Most";\nconst gotowe = true;','typeof null ma historyczny wynik "object".',2),
    term('Number i konwersja pola','value pola formularza jest tekstem. Przed konwersją sprawdź, czy użytkownik coś wpisał.','const tekst = pole.value.trim();\nconst n = Number(tekst);\nconst poprawne = tekst !== "" && Number.isFinite(n);','Number("") daje 0, a Number("12x") daje NaN.'),
    term('Łączenie tekstu i dodawanie','Operator + dodaje liczby albo łączy tekst. Obecność tekstu może zmienić rezultat.','console.log("12" + 5); // "125"\nconsole.log(Number("12") + 5); // 17','toFixed zwraca tekst.'),
    term('===, !== i porównania','Ścisłe porównania sprawdzają zgodność bez konwersji typu. Nierówności służą do badania granic.','const jestDwojka = 2 === "2"; // false\nconst zakres = n >= 1 && n <= 8;','Zapis 1 <= n <= 8 nie sprawdza matematycznego przedziału.'),
    term('&&, || i !','Połącz warunki logiczne. && wymaga obu prawdziwych warunków, || co najmniej jednego, a ! neguje.','if (n < 1 || n > 8) {\n  wynik.textContent = "Poza zakresem";\n}','&& i || zwracają jeden z operandów, co jest przydatne także poza warunkami.'),
    term('if, else i switch','Wybierz fragment kodu zależnie od warunku lub wartości. W switch dopasowanie wartości jest ścisłe.','if (cena >= 100) {\n  rabat = 10;\n} else {\n  rabat = 0;\n}','Przy switch pamiętaj o break, jeśli kolejne przypadki mają się nie wykonać.'),
    term('Operator warunkowy i ??','Operator ? : wybiera jedną z dwóch wartości. ?? daje wartość zapasową tylko przy null lub undefined.','const cena = premium ? 30 : 20;\nconst opis = produkt.opis ?? "Brak opisu";','Operator || traktuje też 0 i pusty tekst jako wartości wymagające zastąpienia.',2),
  ]},
  {title:'Funkcje, pętle i kolekcje', items:[
    term('function, parametry i return','Funkcja przyjmuje argumenty w parametrach i może oddać wynik. return kończy bieżące wywołanie.','function koszt(cena, ile) {\n  return cena * ile;\n}\nconst suma = koszt(12.5, 4);','Wyświetlenie przez console.log nie zastępuje return.'),
    term('Funkcja strzałkowa','Krótko zapisuje funkcję, szczególnie jako argument metody tablicy. Przy jednym wyrażeniu można pominąć return.','const podwoj = x => x * 2;\nconst ceny = [3, 5].map(podwoj);','Po dodaniu klamer wynik oddaj jawnym return.'),
    term('for','Przejdź po kolejnych indeksach lub liczbach. Sprawdź wartość startową, warunek i krok.','let suma = 0;\nfor (let i = 0; i < liczby.length; i++) {\n  suma += liczby[i];\n}','Ostatni indeks tablicy to length - 1.'),
    term('while i do...while','while testuje warunek przed iteracją. do...while wykonuje blok co najmniej raz.','let n = 0;\nwhile (n < 3) {\n  n++;\n}','Zmieniaj stan użyty w warunku, aby uniknąć nieskończonej pętli.'),
    term('Tablica i length','Tablica przechowuje uporządkowane elementy dostępne przez indeks. length określa długość.','const trasy = ["Park", "Las", "Rzeka"];\nconsole.log(trasy[0], trasy.length); // Park, 3','Pierwszy indeks wynosi 0.'),
    term('push, pop, slice i includes','push dopisuje na końcu, pop usuwa ostatni element, slice kopiuje fragment, includes sprawdza obecność.','const a = [1, 2];\na.push(3);\nconst kopia = a.slice(0, 2);\nconsole.log(a.includes(3)); // true','slice nie zmienia tablicy źródłowej.'),
    term('map i filter','map przekształca każdy element. filter wybiera tylko elementy spełniające warunek.','const ceny = produkty.filter(p => p.dostepny).map(p => p.cena);','Obie metody zwracają nowe tablice.'),
    term('forEach i find','forEach wykonuje funkcję dla każdego elementu. find zwraca pierwsze trafienie lub undefined.','przyciski.forEach(b => b.disabled = false);\nconst tani = produkty.find(p => p.cena < 20);','forEach sam nie zwraca tablicy wynikowej.'),
    term('Obiekt i właściwości','Obiekt grupuje dane pod nazwami. Notacja z kropką odczytuje znaną właściwość, nawiasy pozwalają użyć dynamicznego klucza.','const rower = { nazwa: "Most", cena: 17.5 };\nconsole.log(rower.nazwa, rower["cena"]);','Klucz obiektu jest czymś innym niż indeks tablicy.'),
  ]},
  {title:'DOM i zdarzenia', items:[
    term('querySelector i getElementById','Wyszukaj pojedynczy element dokumentu. querySelector przyjmuje selektor CSS, getElementById sam identyfikator.','const wynik = document.querySelector("#wynik");\nconst pole = document.getElementById("godziny");','Obie metody mogą zwrócić null. Podłącz skrypt po utworzeniu elementów, np. przez defer.'),
    term('querySelectorAll','Zwraca statyczną listę elementów pasujących do selektora. Możesz przejść po niej forEach.','document.querySelectorAll(".karta").forEach(k => {\n  k.classList.add("gotowe");\n});','Wynik może być pustą listą.'),
    term('textContent i innerHTML','textContent wstawia zwykły tekst. innerHTML parsuje tekst jako znaczniki. Do wyświetlania wyniku lub danych użytkownika wybieraj textContent.','wynik.textContent = "Koszt: " + suma + " zł";','Tekst wpisany przez użytkownika w innerHTML może stać się wykonywalnym interfejsem.'),
    term('value, checked i selectedOptions','Odczytaj treść pola, zaznaczenie checkboxa lub wybrane opcje listy.','const ile = Number(pole.value);\nconst zRabatem = checkbox.checked;\nconst opcja = lista.selectedOptions[0];','Checkbox sprawdzaj przez checked, zamiast porównywać value do true.'),
    term('classList','Dodaj, usuń lub przełącz klasę bez nadpisania pozostałych klas elementu.','panel.classList.toggle("otwarty");\npanel.classList.add("gotowy");','W classList podawaj nazwę bez kropki.'),
    term('src, alt i dataset','Zmień źródło i opis obrazu albo odczytaj własne atrybuty data-*. Dataset zwraca wartości jako tekst.','duze.src = mini.src;\nduze.alt = mini.alt;\nconst cena = Number(opcja.dataset.cena);','Zmieniaj alt razem ze zdjęciem, gdy zmienia się jego treść.'),
    term('addEventListener','Podepnij funkcję do zdarzenia bez zastępowania innych słuchaczy. Najczęściej użyjesz click, input, change i submit.','przycisk.addEventListener("click", () => {\n  wynik.textContent = "Gotowe";\n});','Przekaż funkcję. Wywołanie oblicz() wykonałoby ją natychmiast.'),
    term('event.target i preventDefault','target wskazuje element, z którego pochodzi zdarzenie. preventDefault blokuje domyślne działanie, np. przeładowanie formularza kalkulatora.','form.addEventListener("submit", event => {\n  event.preventDefault();\n  przelicz();\n});','preventDefault nie zatrzymuje sam z siebie propagacji zdarzenia.'),
  ]},
  {title:'Walidacja i wynik', items:[
    term('Number.isFinite i Number.isInteger','Sprawdź skończoną liczbę i jej całkowitość po świadomej konwersji. W połączeniu z zakresem walidujesz formularz.','const n = Number(pole.value);\nconst ok = pole.value.trim() !== "" && Number.isInteger(n) && n >= 1 && n <= 8;','parseInt może zaakceptować początek tekstu, np. parseInt("2x", 10) daje 2.'),
    term('Math.round, floor, ceil i random','Zaokrąglij do najbliższej liczby całkowitej, w dół, w górę lub pobierz losowy ułamek z przedziału od 0 do wartości mniejszej niż 1.','const minuty = Math.round(godziny * 60);\nconst kostka = Math.floor(Math.random() * 6) + 1;','Math.random() nie jest przeznaczone do generowania bezpiecznych haseł.',2),
    term('toFixed i Intl.NumberFormat','toFixed tworzy tekst ze stałą liczbą miejsc. Intl.NumberFormat uwzględnia lokalny zapis, walutę i separatory.','const format = new Intl.NumberFormat("pl-PL", { style: "currency", currency: "PLN" });\nwynik.textContent = format.format(12.5);','Do dalszych obliczeń zachowaj surową liczbę.'),
    term('String.trim, toLowerCase i includes','Usuń zewnętrzne białe znaki, zamień litery na małe i wyszukaj fragment. To dobry zestaw do prostego filtra.','const haslo = szukaj.value.trim().toLowerCase();\nconst pasuje = nazwa.toLowerCase().includes(haslo);','trim nie usuwa odstępów wewnątrz tekstu.'),
    term('setTimeout i setInterval','Uruchom funkcję po opóźnieniu lub cyklicznie. Dla zegara egzaminu wyliczaj pozostały czas z terminu końca.','const koniec = Date.now() + 60000;\nconst timer = setInterval(() => {\n  wynik.textContent = Math.max(0, koniec - Date.now());\n}, 1000);','Odmierzanie samą liczbą wywołań interval może się rozjechać po ukryciu karty.',2),
    term('JSON i localStorage','JSON serializuje dane do tekstu. localStorage przechowuje tekst lokalnie dla pochodzenia strony.','localStorage.setItem("postep", JSON.stringify({ lekcja: 3 }));\nconst zapis = JSON.parse(localStorage.getItem("postep"));','Odczyt i parsowanie mogą się nie udać. Użyj try/catch, jeśli funkcja ma działać również bez magazynu.',2),
    term('console i debugowanie','Wyświetl wartości pośrednie i sprawdź błędy. Console pomaga rozdzielić błąd wyboru elementu, obliczenia i wyświetlania.','console.log({ tekst: pole.value, liczba: Number(pole.value) });','Przy null sprawdź selektor i moment wykonania skryptu.'),
  ]},
];

const phpGroups = [
  {title:'Składnia i przepływ', items:[
    term('Znaczniki PHP i serwer','Fragment między <?php i ?> wykonuje interpreter PHP na serwerze. Przeglądarka otrzymuje wygenerowaną odpowiedź.','<?php\necho "<p>Gotowe</p>";','Otwieraj aplikację przez serwer, np. localhost, aby kod się wykonał.'),
    term('Zmienne i przypisanie','Nazwy zmiennych zaczynają się od $. Operator = przypisuje wartość. Nazwy zmiennych rozróżniają wielkość liter.','<?php\n$cena = 12.5;\n$ile = 4;\n$suma = $cena * $ile;','Cena i cena to różne nazwy zmiennych.'),
    term('echo i łączenie tekstu','echo wypisuje tekst odpowiedzi. Kropka łączy ciągi znaków.','<?php\n$kwota = 50;\necho "<p>Koszt: " . $kwota . " zł</p>";','Dla dynamicznych danych tekstowych zastosuj kodowanie do HTML.'),
    term('Cudzysłowy i interpolacja','W podwójnych cudzysłowach PHP może wstawić wartości zmiennych. Pojedyncze zwykle traktują tekst dosłownie.','<?php\n$imie = "Ola";\necho "Witaj, $imie";\necho \'Witaj, \' . $imie;','W tekście HTML dobieraj znaki tak, aby nie zamknąć przypadkiem ciągu.'),
    term('Typy i rzutowanie','Rozróżniaj int, float, string, bool, array i null. Jawne rzutowanie zmienia typ, ale samo nie potwierdza poprawności wejścia.','<?php\n$liczba = (int) "12";\n$kwota = (float) "12.50";','(int) "12x" nie zastępuje walidacji pola.'),
    term('===, !== i warunki','Porównanie ścisłe uwzględnia typ. Przy walidacji odróżniaj false, null i poprawne 0, jeśli zero należy do zakresu.','<?php\nif ($n === false || $n === null) {\n    echo "Błędna wartość";\n}','Zapis if (!$n) odrzuci też wartość 0.'),
    term('if, elseif i else','Wykonuj odpowiedni blok po spełnieniu warunku. Kolejność testów może zmieniać wybraną gałąź.','<?php\nif ($suma >= 100) {\n    $rabat = 10;\n} else {\n    $rabat = 0;\n}','Przetestuj wartość dokładnie równą progowi.'),
    term('Funkcje i return','Funkcja przyjmuje argumenty i może zwrócić wartość do dalszego użycia.','<?php\nfunction koszt($cena, $ile) {\n    return $cena * $ile;\n}\necho koszt(12.5, 4);','Zmienne z zewnętrznego zakresu nie stają się automatycznie zmiennymi lokalnymi funkcji.'),
  ]},
  {title:'Tablice i narzędzia', items:[
    term('Tablica indeksowana i asocjacyjna','Indeksowana przechowuje sekwencję, asocjacyjna pary klucz–wartość. Rekord z fetch_assoc ma klucze według kolumn.','<?php\n$ceny = [12, 18, 25];\n$rower = ["nazwa" => "Most", "cena" => 17.5];\necho $rower["nazwa"];','Dla nazwy klucza tekstowego używaj cudzysłowu.'),
    term('foreach','Przejdź po wartościach lub parach klucz–wartość. Sprawdza się do generowania list i sumowania danych.','<?php\n$suma = 0;\nforeach ($ceny as $cena) {\n    $suma += $cena;\n}','Zmiennej sumy nadaj wartość początkową.'),
    term('for i while','for przydaje się do liczników. while wykonuje kod, dopóki warunek jest prawdziwy, np. podczas pobierania kolejnych rekordów.','<?php\nfor ($i = 0; $i < count($ceny); $i++) {\n    echo $ceny[$i];\n}','Nie używaj indeksu równego count tablicy.'),
    term('count, in_array i array_keys','Policz elementy, sprawdź obecność wartości lub pobierz klucze. Tryb ścisły in_array zapobiega dopasowaniom po konwersji.','<?php\n$jest = in_array(2, [1, 2, 3], true);\n$liczba = count($ceny);','Domyślny tryb in_array może konwertować typy.',2),
    term('isset, empty i ??','isset sprawdza istnienie i wartość różną od null. ?? daje domyślną wartość. empty uznaje m.in. "0" za pustą wartość.','<?php\n$miasto = $_POST["miasto"] ?? "";\nif (isset($_POST["zapisz"])) { /* obsłuż */ }','Dla poprawnego zera empty może prowadzić do błędnej walidacji.'),
    term('trim i mb_strlen','trim usuwa zewnętrzne białe znaki. mb_strlen liczy znaki z uwzględnieniem kodowania, jeśli dostępne jest rozszerzenie mbstring.','<?php\n$nazwa = trim($tekst);\n$dlugosc = mb_strlen($nazwa, "UTF-8");','strlen liczy bajty, co przy UTF-8 może dawać większą liczbę niż liczba liter.',2),
    term('number_format i round','number_format przygotowuje tekst do wyświetlenia. round zaokrągla liczbę do wskazanej dokładności.','<?php\necho number_format(12.5, 2, ",", " ") . " zł";','Tekstu z przecinkiem i walutą używaj jako formatu prezentacji.'),
    term('include i require','Wczytaj wspólny fragment kodu lub konfigurację. Warianty once zapobiegają ponownemu dołączeniu tego samego pliku.','<?php\nrequire_once "db.php";\ninclude "naglowek.php";','require przy błędzie dołączenia przerywa dalsze wykonanie. Ścieżkę ustalaj w kodzie.',2),
  ]},
  {title:'Formularze i wyjście', items:[
    term('$_GET i $_POST','Odczytaj pola przesłane odpowiednią metodą. Klucz tablicy odpowiada name kontrolki formularza.','<?php\n$nazwa = $_POST["nazwa"] ?? "";\n$id = $_GET["id"] ?? null;','id elementu HTML służy innym celom niż name.'),
    term('Rozpoznanie metody żądania','Przed obsługą zapisu sprawdź, czy użytkownik wysłał formularz przez POST.','<?php\nif ($_SERVER["REQUEST_METHOD"] === "POST") {\n    // odczytaj i sprawdź pola\n}','Przy pierwszym wejściu przez GET dane POST mogą być nieobecne.'),
    term('filter_input i FILTER_VALIDATE_INT','Pobierz i zwaliduj wejście w jednym kroku. Zwrócony false oznacza niepoprawną wartość, a null brak zmiennej.','<?php\n$n = filter_input(INPUT_POST, "ile", FILTER_VALIDATE_INT,\n    ["options" => ["min_range" => 1, "max_range" => 8]]);','Sprawdzaj false i null ścisłymi porównaniami.'),
    term('FILTER_VALIDATE_EMAIL','Sprawdź składnię tekstu jako adresu e-mail. Walidacja działa po stronie serwera.','<?php\n$email = filter_input(INPUT_POST, "email", FILTER_VALIDATE_EMAIL);\nif ($email === false || $email === null) {\n    echo "Podaj poprawny e-mail.";\n}','Walidacja składni nie dowodzi, że skrzynka istnieje.'),
    term('htmlspecialchars','Zakoduj znaki specjalne przy wypisywaniu tekstu w HTML. ENT_QUOTES obejmuje obydwa rodzaje cudzysłowów.','<?php\necho htmlspecialchars($nazwa, ENT_QUOTES | ENT_SUBSTITUTE, "UTF-8");','Kodowanie HTML nie zastępuje parametrów SQL.'),
    term('header i przekierowanie','Wyślij nagłówek odpowiedzi przed treścią. Przekierowanie po zapisie pomaga uniknąć ponownego wysyłania formularza po odświeżeniu.','<?php\nheader("Location: lista.php");\nexit;','Przed header nie wypisuj HTML ani pustych znaków.',2),
    term('Sesja i session_start','Przechowuj stan przypisany do sesji po stronie serwera. Rozpocznij sesję przed odpowiedzią HTML.','<?php\nsession_start();\n$_SESSION["widoki"] = ($_SESSION["widoki"] ?? 0) + 1;','Dane sesji nie są zwykłymi zmiennymi JavaScript.',2),
    term('Ciasteczka i pliki','setcookie ustawia nagłówek ciasteczka. file_get_contents i file_put_contents służą do prostego odczytu i zapisu plików.','<?php\nfile_put_contents("notatka.txt", "Powtórz JOIN");\n$tekst = file_get_contents("notatka.txt");','Przetestuj uprawnienia i wynik operacji. Podawaj kontrolowane ścieżki plików.',2),
  ]},
  {title:'mysqli i baza danych', items:[
    term('new mysqli','Otwórz połączenie z bazą, podając host, użytkownika, hasło i nazwę bazy. W przykładach używaj lokalnego konta ćwiczebnego.','<?php\n$db = new mysqli("localhost", "uczen", "haslo_lokalne", "inf03");','Dopasuj dane do przygotowanego środowiska.'),
    term('set_charset','Ustal kodowanie połączenia. utf8mb4 obsługuje pełny zestaw znaków Unicode w MySQL/MariaDB.','<?php\n$db->set_charset("utf8mb4");','Spójność kodowania bazy, połączenia i HTML pomaga zachować polskie litery.'),
    term('query dla stałego zapytania','Wykonaj zapytanie o ustalonej treści. SELECT zwraca obiekt wyniku, który można przeglądać.','<?php\n$wynik = $db->query("SELECT nazwa, cena FROM produkty ORDER BY nazwa");','Wartości podawane przez użytkownika przekazuj przez parametry.'),
    term('fetch_assoc i num_rows','fetch_assoc pobiera następny wiersz jako tablicę asocjacyjną. num_rows pozwala rozpoznać pusty wynik.','<?php\nwhile ($r = $wynik->fetch_assoc()) {\n    echo htmlspecialchars($r["nazwa"], ENT_QUOTES, "UTF-8");\n}','Klucz w tablicy musi odpowiadać nazwie lub aliasowi kolumny w SELECT.'),
    term('prepare','Przygotuj zapytanie z miejscami ? na wartości. Konstrukcja SQL jest ustalona osobno od danych wejściowych.','<?php\n$stmt = $db->prepare("SELECT nazwa FROM produkty WHERE id = ?");','Parametr zastępuje wartość, a nie nazwę tabeli lub kolumny.'),
    term('bind_param i execute','Przypisz typy i zmienne do miejsc ?. i oznacza int, d double, s string, b dane binarne. Następnie wykonaj zapytanie.','<?php\n$stmt->bind_param("i", $id);\n$stmt->execute();','Liczba typów i zmiennych musi odpowiadać liczbie znaków ?.'),
    term('bind_result i fetch','Odbierz kolumny przygotowanego SELECT do zmiennych i przejdź po kolejnych rekordach.','<?php\n$stmt->bind_result($nazwa);\nwhile ($stmt->fetch()) {\n    echo htmlspecialchars($nazwa, ENT_QUOTES, "UTF-8");\n}','Zmiennych wynikowych podaj tyle, ile kolumn wybrało zapytanie.'),
    term('close i obsługa błędów','Zamknij instrukcję i połączenie, gdy są gotowe. W ćwiczeniach raportuj błąd na etapie diagnozy i sprawdź, czy problem dotyczy połączenia czy SQL.','<?php\nmysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);\n// po wykonaniu zadania:\n$stmt->close();\n$db->close();','Zapisz zrzut wyniku działania zgodnie z wymaganiami arkusza.'),
  ]},
];

const htmlPatterns = [
  pattern('Szkielet dokumentu z plikami zewnętrznymi','Odtwórz podstawę strony, zanim zaczniesz budować jej sekcje.','<!doctype html>\n<html lang="pl">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Katalog</title>\n  <link rel="stylesheet" href="style.css">\n  <script src="app.js" defer></script>\n</head>\n<body>\n  <main><h1>Katalog</h1></main>\n</body>\n</html>',['DOCTYPE przed html.','UTF-8 i język pl.','Zgodne ścieżki do CSS i JS.']),
  pattern('Semantyczny układ strony','Nazwij rolę obszarów i dodaj nawigację po identyfikatorach.','<header><h1>Rowerem po mieście</h1></header>\n<nav><a href="#oferta">Oferta</a><a href="#kontakt">Kontakt</a></nav>\n<main>\n  <section id="oferta"><h2>Oferta</h2><p>Opis</p></section>\n  <section id="kontakt"><h2>Kontakt</h2><p>Telefon</p></section>\n</main>\n<footer>Wypożyczalnia miejska</footer>',['Jedna główna treść main.','Hierarchia h1 i h2.','Każde href # prowadzi do istniejącego id.']),
  pattern('Formularz POST i etykieta','Wprowadź wartość, którą odbierze PHP pod właściwą nazwą.','<form action="zapis.php" method="post">\n  <label for="email">E-mail</label>\n  <input type="email" id="email" name="email" required>\n  <button type="submit">Zapisz</button>\n</form>',['for odpowiada id.','name tworzy klucz danych.','Walidacja również na serwerze.']),
  pattern('Tabela z nagłówkiem i podpisem','Użyj tabeli do uporządkowanych danych.','<table>\n  <caption>Cennik</caption>\n  <thead><tr><th scope="col">Model</th><th scope="col">Cena</th></tr></thead>\n  <tbody><tr><td>Most</td><td>17,50 zł</td></tr></tbody>\n</table>',['th dla nagłówków.','tr dla wiersza.','td dla komórki danych.']),
  pattern('Lista wyboru i checkbox','Przekaż stawkę do prostego kalkulatora i odczytaj zaznaczenie opcji.','<label for="rower">Rower</label>\n<select id="rower" name="rower">\n  <option value="1" data-cena="12.5">Aleja</option>\n  <option value="2" data-cena="17.5">Most</option>\n</select>\n<label><input type="checkbox" id="dodatek"> Dodaj kask</label>\n<button type="button" id="oblicz">Oblicz</button>\n<output id="wynik"></output>',['value jest identyfikatorem.','data-cena ma surowy zapis liczby.','Przycisk JS ma type button.']),
  pattern('Ilustracja i zagnieżdżona lista','Połącz opis obrazu z listą danych bez zgubienia struktury.','<figure>\n  <img src="img/trasa.jpg" alt="Trasa wzdłuż rzeki" width="900" height="600">\n  <figcaption>Trasa rodzinna</figcaption>\n</figure>\n<ul>\n  <li>Trasa A\n    <ul><li>Dystans 7 km</li><li>Poziom łatwy</li></ul>\n  </li>\n</ul>',['Lista wewnętrzna znajduje się w li.','alt opisuje treść ilustracji.','Sprawdź rzeczywisty format i wymiary obrazu.']),
];
const cssPatterns = [
  pattern('Podstawowy arkusz','Ustal model pudełkowy i podstawę typografii, a potem style sekcji.','* { box-sizing: border-box; }\nbody { margin: 0; color: #17202a; background: #f3f5f7; font-family: Arial, sans-serif; }\nmain { max-width: 1100px; margin: 0 auto; padding: 24px; }\nheader, footer { background: #24445a; color: white; padding: 20px; }',['Wspólny border-box.','Dwa selektory grupuj przecinkiem.']),
  pattern('Dwie kolumny z przełączeniem','Odtwórz proporcję 2:1 na szerokim ekranie i jedną kolumnę na telefonie.','.uklad { display: grid; grid-template-columns: 2fr 1fr; gap: 24px; }\n@media (max-width: 700px) {\n  .uklad { grid-template-columns: 1fr; }\n}',['Zapytanie obejmuje 700px.','Sprawdź także 701px.']),
  pattern('Menu i fokus','Ustaw linki obok siebie, pozwól im przejść do następnego wiersza i zostaw widoczny fokus.','nav { display: flex; flex-wrap: wrap; gap: 12px; }\nnav a { color: inherit; padding: 8px; }\nnav a:hover { background: #dbe6ef; }\na:focus-visible, button:focus-visible { outline: 3px solid #31658a; }',['Flex na rodzicu.','Stan :hover i :focus-visible.']),
  pattern('Tabela i zebra','Zadbaj o czytelne dane oraz obramowania bez podwójnych linii.','table { width: 100%; border-collapse: collapse; }\nth, td { border: 1px solid #8493a0; padding: 8px; text-align: left; }\nthead { background: #24445a; color: white; }\ntbody tr:nth-child(even) { background: #e4edf3; }',['Parzyste tr tylko w tbody.','th i td mają wspólną regułę.']),
  pattern('Galeria kart','Ustaw trzy równe kolumny i obrazy przycięte do stałych proporcji.','.galeria { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }\n.galeria img { width: 100%; aspect-ratio: 3 / 2; object-fit: cover; }\n@media (max-width: 650px) { .galeria { grid-template-columns: 1fr; } }',['Proporcje ustala aspect-ratio.','Cover może przyciąć krawędzie obrazu.']),
  pattern('Kolumny spotykane w starszych arkuszach','Rozpoznaj układ z float i poprawnie zakończ opływanie.','.lewa { float: left; width: 70%; }\n.prawa { float: left; width: 30%; }\nfooter { clear: both; }',['Szerokości dotyczą obrysów przy border-box.','Stopka kończy opływanie.']),
];
const sqlPatterns = [
  pattern('Filtrowanie, sortowanie i limit','Wybierz wymagane kolumny z właściwym warunkiem i kolejnością.','SELECT nazwa, cena\nFROM produkty\nWHERE aktywny = 1 AND cena <= 30\nORDER BY cena ASC, nazwa ASC\nLIMIT 5;',['SELECT określa kolumny.','WHERE wybiera rekordy.','ORDER BY ustala wynik.']),
  pattern('Pozycje z nazwą kategorii','Połącz rekordy według klucza obcego.','SELECT p.nazwa, t.nazwa AS kategoria\nFROM produkty AS p\nINNER JOIN typy AS t ON p.typ_id = t.id\nORDER BY p.nazwa;',['Alias przed nazwą kolumny.','Warunek odpowiada relacji.']),
  pattern('Kategorie również z wynikiem zero','Policz tylko dopasowane pozycje, zachowując wszystkie kategorie.','SELECT t.nazwa, COUNT(p.id) AS liczba\nFROM typy AS t\nLEFT JOIN produkty AS p ON p.typ_id = t.id AND p.aktywny = 1\nGROUP BY t.id, t.nazwa\nORDER BY t.id;',['LEFT JOIN rozpoczyna się od kategorii.','Filtr prawej tabeli w ON.','COUNT(p.id) pomija NULL.']),
  pattern('Warunek po agregacji','Najpierw wybierz rekordy, następnie pokaż grupy spełniające próg.','SELECT typ_id, COUNT(*) AS liczba, AVG(cena) AS srednia\nFROM produkty\nWHERE aktywny = 1\nGROUP BY typ_id\nHAVING COUNT(*) >= 2\nORDER BY liczba DESC;',['WHERE przed GROUP BY.','HAVING po GROUP BY.']),
  pattern('Kontrolowana modyfikacja','Potwierdź zakres przed zmianą i odczytaj rezultat.','SELECT id, cena FROM produkty WHERE id = 4;\nUPDATE produkty SET cena = 17.50 WHERE id = 4;\nSELECT id, cena FROM produkty WHERE id = 4;',['Identyczny warunek WHERE.','Zrzut pokazuje zmianę wymaganego rekordu.']),
  pattern('Założenie relacji i dodanie rekordu','Utwórz tabelę słownikową i tabelę zależną. Najpierw dodaj rekord nadrzędny.','CREATE TABLE typy (id INT PRIMARY KEY, nazwa VARCHAR(50));\nCREATE TABLE produkty (\n  id INT PRIMARY KEY,\n  typ_id INT NOT NULL,\n  nazwa VARCHAR(80) NOT NULL,\n  cena DECIMAL(7,2),\n  FOREIGN KEY (typ_id) REFERENCES typy(id)\n);\nINSERT INTO typy VALUES (1, \'Miejski\');\nINSERT INTO produkty VALUES (4, 1, \'Most\', 17.50);',['Klucz obcy wskazuje istniejące id.','Wartości odpowiadają kolejności kolumn.']),
];
const jsPatterns = [
  pattern('Kalkulator z walidacją','HTML musi zawierać form, input #ile i output #wynik. Odczytaj tekst, sprawdź zakres i dopiero policz.','const form = document.querySelector("form");\nconst pole = document.querySelector("#ile");\nconst wynik = document.querySelector("#wynik");\nform.addEventListener("submit", event => {\n  event.preventDefault();\n  const tekst = pole.value.trim();\n  const ile = Number(tekst);\n  if (tekst === "" || !Number.isInteger(ile) || ile < 1 || ile > 8) {\n    wynik.textContent = "Podaj od 1 do 8 pełnych godzin.";\n    return;\n  }\n  wynik.textContent = (ile * 12.5).toFixed(2) + " zł";\n});',['Skrypt z defer.','Puste pole przed konwersją.','return kończy błędną ścieżkę.']),
  pattern('Rabat od progu','Funkcja zwraca koszt jako liczbę. Testuj próg oraz wartości obok niego.','function koszt(cena, ile) {\n  const razem = cena * ile;\n  return ile >= 4 ? razem * 0.9 : razem;\n}\nconsole.log(koszt(12.5, 4)); // 45',['Rabat 10% oznacza mnożnik 0.9.','Warunek >= obejmuje próg.']),
  pattern('Filtr obiektów','Najpierw wybierz dostępne pozycje, potem zwróć ich nazwy.','const produkty = [\n  { nazwa: "Most", cena: 18, aktywny: true },\n  { nazwa: "Park", cena: 25, aktywny: false }\n];\nconst nazwy = produkty\n  .filter(p => p.aktywny && p.cena <= 20)\n  .map(p => p.nazwa);\nconsole.log(nazwy); // ["Most"]',['filter wybiera.','map przekształca.']),
  pattern('Zmiana fotografii','HTML zawiera img #duze i przyciski .miniatura z data-src oraz data-alt.','const duze = document.querySelector("#duze");\ndocument.querySelectorAll(".miniatura").forEach(button => {\n  button.addEventListener("click", () => {\n    duze.src = button.dataset.src;\n    duze.alt = button.dataset.alt;\n  });\n});',['Zdarzenie click na przycisku obsłuży też klawiaturę.','Opis alt zmienia się razem z obrazem.']),
  pattern('Suma w pętli','Przejdź po każdym indeksie i zwiększ akumulator.','const liczby = [4, 7, 10];\nlet suma = 0;\nfor (let i = 0; i < liczby.length; i++) {\n  suma += liczby[i];\n}\nconsole.log(suma); // 21',['Start i=0.','Warunek i < length.','Suma początkowa 0.']),
  pattern('Lista wyboru ze stawką','HTML zawiera select #rower z data-cena na option, input #ile i przycisk #oblicz.','const lista = document.querySelector("#rower");\nconst pole = document.querySelector("#ile");\nconst wynik = document.querySelector("#wynik");\ndocument.querySelector("#oblicz").addEventListener("click", () => {\n  const stawka = Number(lista.selectedOptions[0].dataset.cena);\n  const ile = Number(pole.value);\n  wynik.textContent = new Intl.NumberFormat("pl-PL", {\n    style: "currency", currency: "PLN"\n  }).format(stawka * ile);\n});',['Przed obliczeniem w pełnej aplikacji zwaliduj ilość.','data-cena ma zapis np. 12.5.']),
];
const phpPatterns = [
  pattern('Odbiór i walidacja POST','Formularz wysyła name="ile" metodą POST. Rozpoznaj wysyłkę i sprawdź zakres.','<?php\nif ($_SERVER["REQUEST_METHOD"] === "POST") {\n    $ile = filter_input(INPUT_POST, "ile", FILTER_VALIDATE_INT,\n        ["options" => ["min_range" => 1, "max_range" => 8]]);\n    if ($ile === false || $ile === null) {\n        echo "Podaj od 1 do 8 pełnych godzin.";\n    } else {\n        echo number_format($ile * 12.5, 2, ",", " ") . " zł";\n    }\n}',['name zgodne z kluczem.','Sprawdź brak i błąd osobno od liczby.']),
  pattern('Lista z bazy','Użyj lokalnego konta i właściwej bazy. Pobierz nazwy, zakoduj tekst i zbuduj elementy li.','<?php\nmysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);\n$db = new mysqli("localhost", "uczen", "haslo_lokalne", "inf03");\n$db->set_charset("utf8mb4");\n$wynik = $db->query("SELECT nazwa FROM produkty ORDER BY nazwa");\necho "<ul>";\nwhile ($r = $wynik->fetch_assoc()) {\n    echo "<li>" . htmlspecialchars($r["nazwa"], ENT_QUOTES | ENT_SUBSTITUTE, "UTF-8") . "</li>";\n}\necho "</ul>";\n$db->close();',['Połączenie z właściwą bazą.','Kodowanie połączenia i wyjścia.','Pętla pobiera kolejny wiersz.']),
  pattern('SELECT z parametrem','Połącz zwalidowany identyfikator z zapytaniem. Przykład zakłada działające $db.','<?php\n$id = filter_input(INPUT_GET, "id", FILTER_VALIDATE_INT);\nif ($id === false || $id === null || $id < 1) {\n    echo "Niepoprawny identyfikator.";\n} else {\n    $stmt = $db->prepare("SELECT nazwa FROM produkty WHERE id = ?");\n    $stmt->bind_param("i", $id);\n    $stmt->execute();\n    $stmt->bind_result($nazwa);\n    if ($stmt->fetch()) {\n        echo htmlspecialchars($nazwa, ENT_QUOTES, "UTF-8");\n    } else {\n        echo "Brak wyniku.";\n    }\n    $stmt->close();\n}',['id zwalidowane.','? zastępuje wartość.','bind_result odpowiada kolumnom.']),
  pattern('Wiersze tabeli z formatem ceny','Dla wyniku zapytania z kolumnami nazwa i cena wygeneruj komórki HTML.','<?php\necho "<table><thead><tr><th>Nazwa</th><th>Cena</th></tr></thead><tbody>";\nwhile ($r = $wynik->fetch_assoc()) {\n    $nazwa = htmlspecialchars($r["nazwa"], ENT_QUOTES, "UTF-8");\n    $cena = number_format((float) $r["cena"], 2, ",", " ");\n    echo "<tr><td>$nazwa</td><td>$cena zł</td></tr>";\n}\necho "</tbody></table>";',['tr tworzy wiersz.','Cena ma dwa miejsca.','Nazwa zakodowana przed wstawieniem.']),
  pattern('INSERT z dwoma parametrami','Przykład zakłada istniejące $db, zwalidowane zmienne $nazwa oraz $cena i tabelę produkty, w której id ma AUTO_INCREMENT, a pozostałe pominięte kolumny dopuszczają wartości domyślne.','<?php\n$stmt = $db->prepare("INSERT INTO produkty (nazwa, cena) VALUES (?, ?)");\n$stmt->bind_param("sd", $nazwa, $cena);\n$stmt->execute();\n$stmt->close();',['s dla tekstu, d dla liczby zmiennoprzecinkowej.','Wartości sprawdzone przed wykonaniem.']),
  pattern('Bezpieczne wyświetlenie wartości formularza','Walidacja sprawdza przydatność danych, a kodowanie przygotowuje je do konkretnego kontekstu HTML.','<?php\n$imie = $_POST["imie"] ?? "";\nif (!is_string($imie) || trim($imie) === "") {\n    echo "<p>Wpisz imię.</p>";\n} else {\n    $tekst = htmlspecialchars(trim($imie), ENT_QUOTES | ENT_SUBSTITUTE, "UTF-8");\n    echo "<p>Witaj, $tekst.</p>";\n}',['Sprawdź, czy wejście jest tekstem.','Wypisuj zakodowaną wartość.']),
];

