export const referenceSections = [
  {id:'html',title:'HTML',description:'Znaczniki, atrybuty i struktura dokumentu.',groups:[],patterns:htmlPatterns},
  {id:'css',title:'CSS',description:'Selektory, wygląd, układ i responsywność.',groups:cssGroups,patterns:cssPatterns},
  {id:'sql',title:'SQL',description:'Relacje, kwerendy, zmiany danych i administracja.',groups:sqlGroups,patterns:sqlPatterns},
  {id:'php',title:'PHP',description:'Składnia, formularze, generowanie HTML i mysqli.',groups:phpGroups,patterns:phpPatterns},
  {id:'js',title:'JavaScript',description:'Zmienne, funkcje, pętle, DOM i zdarzenia.',groups:jsGroups,patterns:jsPatterns}
];

export function buildTheorySections(data) {
  return referenceSections.map(section => {
    if(section.id !== 'html') return section;
    const groups = [...new Set(data.znaczniki.map(item => item.group))].map(title => ({
      title, items:data.znaczniki.filter(item => item.group === title).map(item => ({
        title:'<'+item.tag+'>', body:item.body, example:item.code, priority:item.priority,
        trap:item.priority === 1 ? 'Odtwórz ten element z pamięci. Sprawdź wymagane atrybuty i zamknięcia w kodzie.' : 'Przykład jest fragmentem. Osadź go we właściwym kontekście dokumentu.'
      }))
    }));
    return {...section,groups};
  });
}
